<script setup>defineProps({label:String,modelValue:[String,Number],type:{default:"text"},maxlength:{default:30},placeholder:String});defineEmits(["update:modelValue"])</script><template><label class="kit-form-row"><text class="kit-label">{{label}}</text><input :value="modelValue" :type="type" :maxlength="maxlength" :placeholder="placeholder" :aria-label="label" @input="$emit('update:modelValue',$event.detail.value)"/></label></template>